      "C": "Benar (Kunci Jawaban), kaidah jaring kubus selang satu kotak: Sisi 2 berhadapan langsung dengan Sisi 4.",
      "D": "Salah, sisi 5 berhadapan dengan sayap kanan (sisi 6).",
